INSERT INTO TB_NOTICE (title,content,writer,view_count,important_yn,reg_date) VALUES
('[중요] 2025년 1학기 수강신청 안내','2025년 1학기 수강신청이 아래와 같이 진행됩니다.\n- 일정: 2025년 2월 17일(월) ~ 2월 21일(금)\n- 방법: 학사포털 > 수강신청 메뉴 이용\n재학생은 지정된 시간에 신청하시기 바랍니다.','관리자',85,'Y','2025-02-10 09:00:00'),
('[중요] 2025년 졸업사정 대상자 안내','2025년 2월 졸업 예정자를 대상으로 졸업사정을 실시합니다.\n대상: 4학년 재학생 중 졸업학점 이수 예정자\n확인 기간: 2025년 1월 6일 ~ 1월 10일\n미확인 시 졸업이 취소될 수 있으니 반드시 확인하세요.','관리자',120,'Y','2025-01-05 09:00:00'),
('2025년 1학기 장학금 신청 안내','교내 장학금 신청을 받습니다.\n- 신청 기간: 2025년 3월 3일 ~ 3월 7일\n- 신청 방법: 학사포털 > 장학 > 장학금 신청\n- 제출 서류: 가정환경조사서, 성적증명서 등\n자세한 사항은 장학팀으로 문의하세요.','관리자',67,'N','2025-02-25 10:00:00'),
('도서관 이용시간 변경 안내','3월부터 중앙도서관 이용시간이 변경됩니다.\n- 평일: 오전 8시 ~ 오후 11시\n- 주말: 오전 9시 ~ 오후 9시\n시험기간에는 24시간 운영됩니다.','관리자',43,'N','2025-02-28 11:00:00'),
('캡스톤디자인 발표회 개최 안내','2025년 1학기 캡스톤디자인 최종 발표회가 개최됩니다.\n- 일시: 2025년 6월 20일(금) 10:00 ~ 17:00\n- 장소: 공학관 대강의실\n참가 팀은 3월 15일까지 지도교수 승인을 받으세요.','관리자',38,'N','2025-03-05 09:00:00'),
('2025년 1학기 성적 공시 안내','2025년 1학기 성적이 공시됩니다.\n- 공시 기간: 2025년 6월 30일 ~ 7월 4일\n- 확인 방법: 학사포털 > 성적조회\n성적 이의신청은 공시 기간 내에만 가능합니다.','관리자',55,'N','2025-06-28 09:00:00'),
('해외 교환학생 프로그램 안내','2025년 2학기 해외 교환학생 프로그램을 모집합니다.\n- 파견 국가: 미국, 일본, 독일, 호주 등 15개국\n- 지원 자격: 2학년 이상, GPA 3.0 이상\n- 지원 기간: 2025년 3월 10일 ~ 3월 24일','관리자',92,'N','2025-03-01 10:00:00'),
('동아리 박람회 개최 안내','신입생 및 재학생을 위한 동아리 박람회가 열립니다.\n- 일시: 2025년 3월 12일(수) 11:00 ~ 16:00\n- 장소: 학생회관 앞 광장\n다양한 동아리 활동을 직접 체험해보세요!','관리자',41,'N','2025-03-07 09:00:00'),
('인턴십 프로그램 참가자 모집','하계 인턴십 프로그램 참가자를 모집합니다.\n- 참가 기간: 2025년 7월 1일 ~ 8월 29일\n- 모집 인원: 20명\n- 지원 방법: 취업지원팀 방문 또는 이메일 지원','관리자',76,'N','2025-03-15 10:00:00'),
('학생증 재발급 신청 안내','학생증 분실 또는 훼손 시 아래 절차로 재발급 신청하세요.\n- 신청처: 학생처 창구 또는 학사포털 온라인 신청\n- 수수료: 5,000원\n- 처리 기간: 신청일로부터 5일 이내','관리자',29,'N','2025-02-20 09:00:00'),
('AI융합 특강 안내','산업계 전문가를 초청한 AI융합 특강을 개최합니다.\n- 일시: 2025년 4월 5일(토) 13:00 ~ 17:00\n- 장소: 정보관 세미나실\n- 강사: 네이버 AI 연구소 김철수 박사\n참가 신청은 3월 28일까지 마감합니다.','관리자',63,'N','2025-03-20 10:00:00'),
('취업박람회 개최 안내','2025 하반기 취업박람회가 개최됩니다.\n- 일시: 2025년 9월 11일(목) 10:00 ~ 17:00\n- 장소: 체육관\n- 참여 기업: 삼성, LG, SK, 카카오 등 50개사\n이력서를 미리 준비하세요!','관리자',88,'N','2025-08-20 09:00:00'),
('기말시험 일정 안내','2025년 1학기 기말시험 일정을 안내합니다.\n- 기간: 2025년 6월 16일(월) ~ 6월 20일(금)\n- 장소: 각 강의실 (시간표 참조)\n부정행위 적발 시 해당 과목 0점 처리되오니 유의하세요.','관리자',97,'N','2025-06-05 09:00:00'),
('2024년 2학기 성적 이의신청 안내','2024년 2학기 성적에 이의가 있는 경우 신청하세요.\n- 신청 기간: 2025년 1월 13일 ~ 1월 17일\n- 신청 방법: 학사포털 > 성적 > 이의신청\n- 처리 기간: 신청 후 7일 이내','관리자',34,'N','2025-01-11 09:00:00'),
('코딩 경진대회 개최 안내','제10회 교내 알고리즘 코딩 경진대회를 개최합니다.\n- 일시: 2025년 5월 10일(토) 10:00 ~ 14:00\n- 참가 자격: 재학생 누구나\n- 상금: 1위 50만원, 2위 30만원, 3위 20만원','관리자',51,'N','2025-04-15 10:00:00'),
('2025년 2학기 수강신청 안내','2025년 2학기 수강신청이 아래와 같이 진행됩니다.\n- 일정: 2025년 7월 28일(월) ~ 8월 1일(금)\n- 방법: 학사포털 > 수강신청 메뉴 이용\n수강신청 전 선수과목 이수 여부를 확인하세요.','관리자',72,'N','2025-07-20 09:00:00'),
('국가근로장학생 모집 안내','2025년 2학기 국가근로장학생을 모집합니다.\n- 모집 기간: 2025년 7월 7일 ~ 7월 18일\n- 근로 시간: 주 15시간 이내\n- 시급: 최저임금 이상\n한국장학재단 홈페이지에서 신청하세요.','관리자',39,'N','2025-07-01 10:00:00'),
('전과 신청 안내','2025년 2학기 전과 신청을 받습니다.\n- 신청 기간: 2025년 7월 14일 ~ 7월 18일\n- 신청 자격: 재학생 (1학년 제외)\n- 신청 방법: 학사포털 > 학적 > 전과신청\n자세한 사항은 학사팀으로 문의하세요.','관리자',28,'N','2025-07-07 09:00:00'),
('복수전공 신청 안내','2025년 2학기 복수전공 신청을 받습니다.\n- 신청 기간: 2025년 7월 14일 ~ 7월 18일\n- 신청 자격: 2학년 이상, 평점평균 3.0 이상\n- 정원 내 선착순 허가\n복수전공은 졸업 시 학위가 2개 부여됩니다.','관리자',33,'N','2025-07-07 10:00:00'),
('학술제 참가 안내','2025 학술제에 참가할 팀을 모집합니다.\n- 일시: 2025년 11월 14일(금) 13:00 ~ 18:00\n- 참가 형태: 포스터 발표 또는 구두 발표\n- 참가 신청: 10월 31일까지\n우수 작품은 논문지에 게재될 수 있습니다.','관리자',22,'N','2025-10-15 09:00:00'),
('개인정보 처리방침 개정 안내','학사시스템 개인정보 처리방침이 개정되었습니다.\n- 시행일: 2025년 3월 1일\n- 주요 변경사항: 개인정보 보유기간 명확화, 제3자 제공 항목 추가\n자세한 내용은 학사포털 공지사항을 확인하세요.','관리자',18,'N','2025-02-20 14:00:00'),
('학생 심리상담 프로그램 안내','학생 심리건강을 위한 무료 상담 프로그램을 운영합니다.\n- 대상: 재학생 누구나\n- 운영: 매주 월~금 09:00 ~ 17:00\n- 신청: 학생상담센터 방문 또는 전화 예약\n모든 상담 내용은 비밀이 보장됩니다.','관리자',47,'N','2025-03-10 10:00:00'),
('SW교육 의무이수 안내','졸업을 위한 SW교육 의무이수 기준을 안내합니다.\n- 대상: 2022학번 이후 전 학생\n- 이수 기준: SW 관련 과목 6학점 이상\n- 미이수 시 졸업 불가\n이수 현황은 학사포털에서 확인 가능합니다.','관리자',56,'N','2025-02-15 09:00:00'),
('봉사활동 인정 기준 안내','교내 봉사활동 학점 인정 기준을 안내합니다.\n- 인정 시간: 30시간 이상 시 1학점 인정\n- 인정 기관: 사회복지시설, 공공기관 등 지정 기관\n- 신청 방법: 활동 완료 후 학생처 제출\n봉사활동 확인서는 반드시 직인이 찍혀있어야 합니다.','관리자',31,'N','2025-03-20 11:00:00'),
('교내 창업경진대회 안내','2025 교내 창업경진대회 참가팀을 모집합니다.\n- 참가 자격: 재학생 2~5인 팀\n- 접수 기간: 2025년 4월 1일 ~ 4월 15일\n- 발표 심사: 2025년 5월 20일\n- 총 상금: 500만원\n아이디어를 현실로 만들어 보세요!','관리자',44,'N','2025-03-25 10:00:00'),
('2025년 하계 방학 일정 안내','2025년 하계 방학 일정을 안내합니다.\n- 방학 기간: 2025년 6월 27일 ~ 8월 26일\n- 개강일: 2025년 8월 27일(수)\n방학 중 도서관 및 체육시설 이용 가능합니다.','관리자',62,'N','2025-06-20 09:00:00'),
('[중요] 2025년 2학기 등록금 납부 안내','2025년 2학기 등록금 납부 기간을 안내합니다.\n- 납부 기간: 2025년 8월 4일 ~ 8월 8일\n- 납부 방법: 가상계좌 또는 학사포털 카드 결제\n기간 내 미납 시 수강신청이 취소될 수 있습니다.','관리자',104,'Y','2025-07-25 09:00:00'),
('기숙사 입사 신청 안내','2025년 2학기 기숙사 입사 신청을 받습니다.\n- 신청 기간: 2025년 7월 21일 ~ 7월 25일\n- 신청 방법: 학사포털 > 기숙사 > 입사신청\n- 선발 기준: 거리, 성적, 소득 종합 점수\n합격자는 8월 8일에 발표됩니다.','관리자',58,'N','2025-07-15 10:00:00'),
('사이버 강의 수강 방법 안내','온라인 사이버 강의 수강 방법을 안내합니다.\n- 접속 주소: e-learning 시스템\n- 권장 브라우저: Chrome 최신버전\n- 강의 진도율 80% 이상 달성 시 출석 인정\n기술적 문제 발생 시 IT지원팀(내선 1234)으로 문의하세요.','관리자',27,'N','2025-03-03 09:00:00'),
('시스템 정기 점검 안내','학사포털 시스템 정기 점검이 실시됩니다.\n- 점검 일시: 2025년 6월 7일(토) 00:00 ~ 06:00\n- 점검 범위: 학사포털 전체 서비스\n점검 시간 동안 모든 서비스 이용이 불가합니다.\n불편을 드려 죄송합니다.','관리자',15,'N','2025-06-04 14:00:00');

